correct_example.code:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract ZkSyncBridge {
    // @audit correct block period: 12 seconds (Ethereum PoS slot time)
    uint256 public constant BLOCK_PERIOD = 12;
    uint256 public constant PRIORITY_EXPIRATION_BLOCKS = 86400; // 7 days

    function calculateExpiration() external view returns (uint256) {
        // @audit uses 12s per block, matches zkSync system contract logic
        return block.timestamp + PRIORITY_EXPIRATION_BLOCKS * BLOCK_PERIOD;
    }

    function submitPriorityTx(bytes calldata _data) external payable {
        uint256 expiration = calculateExpiration();
        // ... submit to zkSync priority queue with expiration
    }
}
